ctx.lineWidth = 9; ctx.strokeStyle = 'rgba(20, 40, 70, 0.95)'; ctx.stroke();
ctx.strokeStyle = wc;
ctx.globalAlpha = 0.06 + 0.05 * pulse; ctx.lineWidth = 18; ctx.stroke();
ctx.globalAlpha = 0.14 + 0.08 * pulse; ctx.lineWidth = 9; ctx.stroke();
