function buildTitleItems() {
titleItems = [];
if (hasSave(false)) {
let sub = 'Pick up where you left off';
try { const o = JSON.parse(api.load(saveKey(false))); if (o && typeof o.mi === 'number') sub = (o.mi >= MS.length ? 'Campaign complete' : 'Milestone ' + (num(o.mi, 0, MS.length, 0) + 1) + ' of ' + MS.length) + ' \u2022 $' + fmtNum(num(o.m, -1e9, 1e12, 0)); } catch (err) { /* keep default */ }
titleItems.push({ id: 'cont', label: 'Continue campaign', sub: sub });
}
titleItems.push({ id: 'new', label: 'New campaign', sub: '12 milestones, from one drill to the Nova Core' });
titleItems.push({ id: 'sand', label: hasSave(true) ? 'Continue sandbox' : 'Sandbox', sub: 'Everything unlocked, unlimited money' });
let bk = false;
try { const s = api.load('backup-campaign'); bk = typeof s === 'string' && s.length > 10; } catch (err) { bk = false; }
if (bk) titleItems.push({ id: 'restore', label: 'Restore backup', sub: 'Bring back the campaign factory you replaced' });
titleSel = 0; confirmNew = 0;
}
