ctx.lineWidth = selc ? 2.5 : 1.5; ctx.strokeStyle = selc ? UI.hi : UI.stroke; ctx.stroke();
const lab = it.id === 'new' && confirmNew > 0 ? 'Replace your saved factory?' : it.label;
const sub = it.id === 'new' && confirmNew > 0 ? (touchUI ? 'Tap again to start over (a backup is kept)' : 'Press again to start over (a backup is kept)') : it.sub;
txt(ctx, lab, LW / 2, iy + 18, 16, FONT_D, selc ? UI.hi : UI.head, 'center', iw - 30);
txt(ctx, sub, LW / 2, iy + 37, 11, FONT_B, UI.body, 'center', iw - 30);
