function buildChart(def) {
const objs = [], sections = [], barX = [];
let x = 0, m = 1, sec = 'I';
const add = function (t, ox, oy, r, mir) {
let y = oy, rr = r || 0;
if (mir) {
y = CEIL - 1 - oy;
if (t === 'spike' && (rr === 0 || rr === 2)) rr = 2 - rr;
if (t === 'pad' || t === 'grav') rr = rr === 0 ? 2 : 0;
}
if (y < 0 || y > CEIL - 1) return;
objs.push({ t: t, x: ox, y: y, r: rr });
};
const toks = def.chart.join(' ').trim().split(/\s+/);
for (const raw of toks) {
if (/^[IBDKO]:$/.test(raw)) { sec = raw[0]; continue; }
if (raw[0] === '>') { const v = clamp(parseInt(raw.slice(1), 10) || 0, 0, 3); m = SPEEDS[v]; objs.push({ t: 'speed', x: x - 0.5, y: 0, r: v }); continue; }
if (raw[0] === '@') { const f = Math.max(0, 'rgf'.indexOf(raw[1])); objs.push({ t: 'phase', x: x - 0.5, y: 0, r: f }); continue; }
let tok = raw, rep = 1;
const star = tok.indexOf('*');
if (star > 0) { rep = Math.max(1, parseInt(tok.slice(star + 1), 10) || 1); tok = tok.slice(0, star); }
for (let k = 0; k < rep; k++) {
barX.push(x);
placeBar(add, tok, x, 4 * m, def.gs || 4);
sections.push(sec);
x += 16 * m;
}
}
objs.push({ t: 'finish', x: x - 0.5, y: 0, r: 0 });
const hints = (def.hints || []).map(function (h) { return { x: (barX[h[0]] || 0) + 2, text: h[1], touch: h[2] || '' }; });
return { objs: objs, sections: sections, hints: hints };
}

function placeBar(add, tok, x0, u, gs) {
let mir = false;
if (tok[0] === '~') { mir = true; tok = tok.slice(1); }
if (tok === '_' || tok.length < 2) return;
const kind = tok[0], body = tok.slice(1), n = body.length, sw = 4 / n;
for (let i = 0; i < n; i++) {
const ch = body[i];
if (ch === '.') continue;
const pb = i * sw, xs = x0 + pb * u;
const wU = Math.max(1, Math.ceil(sw * u - 0.01)), rs = xs - wU / 2;
const row = function (y) { for (let k = 0; k < wU; k++) add('block', rs + k, y, 0, mir); };
const spikes = function (cnt, y) { for (let k = 0; k < cnt; k++) add('spike', xs - cnt / 2 + k, y, 0, mir); };
if (kind === 'r') {
switch (ch) {
case '^': spikes(1, 0); break;
case '2': spikes(2, 0); break;
case '3': spikes(3, 0); break;
case '4': spikes(4, 0); break;
case '#': row(0); break;
case '=': row(0); row(1); break;
case 'T': row(0); row(1); row(2); break;
case 'p': row(1); for (let k = 0; k < wU; k++) add('spike', rs + k, 0, 0, mir); break;
case 'P': row(2); for (let k = 0; k < wU; k++) add('spike', rs + k, 0, 0, mir); break;
case 'a': row(0); spikes(1, 1); break;
case 'b': row(0); row(1); spikes(1, 2); break;
case 'j': add('pad', xs - 0.5, 0, 0, mir); break;
case 'J': row(0); add('pad', xs - 0.5, 1, 0, mir); break;
case 'o': add('ring', xs - 0.5, 2, 0, mir); break;
case 'q': add('ring', xs - 0.5, 3, 0, mir); break;
case 'O': add('ring', xs - 0.5, 4, 0, mir); break;
case 'Q': add('ring', xs - 0.5, 5, 0, mir); break;
case 'g': add('grav', xs - 0.5, 0, 0, mir); break;
case '*': add('saw', xs - 0.5, 0, 0, mir); break;
case '@': add('saw', xs - 0.5, 2, 0, mir); break;
case 'x': add('saw', xs - 0.5, 3, 0, mir); break;
case '_': for (let k = 0; k < wU; k++) add('spike', rs + k, 0, 0, mir); break;
case 'c': add('coin', xs - 0.5, 3, 0, mir); break;
case 'C': add('coin', xs - 0.5, 5, 0, mir); break;
case 'k': add('coin', xs - 0.5, 7, 0, mir); break;
default: break;
}
} else if (kind === 'g') {
if (ch >= '1' && ch <= '7') {
const d = ch.charCodeAt(0) - 48;
const low = clamp(d - Math.floor(gs / 2), 0, CEIL - gs);
for (let y = 0; y < CEIL; y++) if (y < low || y > low + gs - 1) add('block', xs - 0.5, y, 0, mir);
} else if (ch === 'l') add('saw', xs - 0.5, 1, 0, mir);
else if (ch === 'm') add('saw', xs - 0.5, 4, 0, mir);
else if (ch === 'n') add('saw', xs - 0.5, 7, 0, mir);
else if (ch === '_' || ch === '=') { for (let k = 0; k < wU; k++) add('spike', rs + k, 0, 0, mir); }
if (ch === '-' || ch === '=') { for (let k = 0; k < wU; k++) add('spike', rs + k, CEIL - 1, 2, mir); }
else if (ch === 'c') add('coin', xs - 0.5, 7, 0, mir);
else if (ch === 'C') add('coin', xs - 0.5, 1, 0, mir);
else if (ch === 'M') add('coin', xs - 0.5, 4, 0, mir);
} else if (kind === 'f') {
const xc = x0 + (pb + sw / 2) * u, cnt = Math.max(1, Math.round(0.7 * sw * u));
for (let k = 0; k < cnt; k++) {
const cx = xc - cnt / 2 + k;
if (ch === 'u') add('spike', cx, 0, 0, mir);
else if (ch === 'd') add('spike', cx, CEIL - 1, 2, mir);
else if (ch === 'U') { add('block', cx, 0, 0, mir); add('block', cx, 1, 0, mir); }
else if (ch === 'D') { add('block', cx, CEIL - 1, 0, mir); add('block', cx, CEIL - 2, 0, mir); }
}
if (ch === 'c') add('coin', xc - 0.5, 4, 0, mir);
else if (ch === 'm') add('saw', xc - 0.5, 4, 0, mir);
}
}
}

const CUSTOM_SECTIONS = 'IIIIBBBBDDDDDDDDKKKKBBBBDDDDDDDD', CUSTOM_LOOP = 'DDDDDDDDKKKKBBBB';
function compileLevel(src) {
const objs = [];
for (const o of src.objs) objs.push({ t: o.t, x: o.x, y: o.y, r: o.r | 0, used: false, got: false });
objs.sort(function (a, b) { return a.x - b.x || a.y - b.y; });
const phases = [], speeds = [], coins = [];
let finishX = -1, maxX = 0;
for (const o of objs) {
if (o.x > maxX) maxX = o.x;
if (o.t === 'finish') finishX = Math.max(finishX, o.x + 0.5);
else if (o.t === 'phase') phases.push(o);
else if (o.t === 'speed') speeds.push(o);
else if (o.t === 'coin') { o.ci = coins.length; coins.push(o); }
}
if (finishX < 4) finishX = Math.max(32, maxX + 14);
const segs = [{ x: 0, b: 0, m: 1 }];
for (const g of speeds) {
const gx = g.x + 0.5, m = SPEEDS[clamp(g.r, 0, 3)], last = segs[segs.length - 1];
if (gx <= last.x + 1e-6) { last.m = m; continue; }
segs.push({ x: gx, b: last.b + (gx - last.x) / (4 * last.m), m: m });
}
const nB = Math.ceil(Math.max(finishX, maxX)) + 8, buckets = [];
for (let i = 0; i < nB; i++) buckets.push([]);
for (const o of objs) buckets[clamp(Math.floor(o.x) + 2, 0, nB - 1)].push(o);
const L = {
name: src.name, bpm: src.bpm, style: src.style, root: src.root, pal: PALS[src.pal] || PALS[0], bg: src.bg | 0,
objs: objs, phases: phases, speeds: speeds, coins: coins, finishX: finishX, segs: segs, buckets: buckets,
sections: src.sections || null, hints: src.hints || [], custom: !!src.custom, idx: src.idx == null ? -1 : src.idx,
};
L.lenBeats = beatAtX(L, finishX);
return L;
}
function xAtBeat(L, b) {
const s = L.segs;
let i = s.length - 1;
while (i > 0 && s[i].b > b) i--;
return s[i].x + (b - s[i].b) * 4 * s[i].m;
}
function beatAtX(L, x) {
const s = L.segs;
let i = s.length - 1;
while (i > 0 && s[i].x > x) i--;
return s[i].b + (x - s[i].x) / (4 * s[i].m);
}
function speedAtX(L, x) {
const s = L.segs;
let i = s.length - 1;
while (i > 0 && s[i].x > x) i--;
return s[i].m;
}
function sectionAt(L, bar) {
if (bar < 0) return 'I';
if (L.sections) return bar < L.sections.length ? L.sections[bar] : 'O';
return bar < CUSTOM_SECTIONS.length ? CUSTOM_SECTIONS[bar] : CUSTOM_LOOP[(bar - CUSTOM_SECTIONS.length) % CUSTOM_LOOP.length];
}
function kickOn(L, step) {
if (step < 0) return false;
const bar = Math.floor(step / 16), s = step % 16, sec = sectionAt(L, bar), st = STYLES[L.style] || STYLES[0];
if (sec === 'K') return false;
if (sec === 'I' || sec === 'O') return s === 0;
if (sec === 'B') return s % 4 === 0;
return st.kick[s] === 'x';
}

const campaignCache = [];
function campaignLevel(i) {
if (!campaignCache[i]) {
const def = LEVELS[i], b = buildChart(def);
campaignCache[i] = { name: def.name, bpm: def.bpm, style: def.style, root: def.root, pal: def.pal, bg: def.bg,
objs: b.objs, sections: b.sections, hints: b.hints, custom: false, idx: i };
}
return compileLevel(campaignCache[i]);
}

const TYPE_CH = { block: 'b', spike: 's', saw: 'z', pad: 'p', ring: 'o', grav: 'g', speed: 'v', phase: 'f', coin: 'c', finish: 'e' };
const CH_TYPE = {};
Object.keys(TYPE_CH).forEach(function (k) { CH_TYPE[TYPE_CH[k]] = k; });
function hashStr(s) {
let h = 7;
for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 46656;
return h.toString(36).padStart(3, '0');
}
function sanitizeR(t, r) {
r = r | 0;
if (t === 'spike' || t === 'speed') return clamp(r, 0, 3);
if (t === 'pad' || t === 'grav') return r === 2 ? 2 : 0;
if (t === 'phase') return clamp(r, 0, 2);
return 0;
}
function encodeLevel(lv) {
const parts = [];
for (const o of lv.objs) parts.push(TYPE_CH[o.t] + Math.round(o.x).toString(36) + '.' + o.y + (o.r | 0));
const body = 'B1-' + lv.bpm + '-' + lv.style + '-' + parts.join('_');
return body + '-' + hashStr(body);
}
function decodeLevel(str) {
if (typeof str !== 'string') return null;
const s = str.replace(/\s+/g, '');
const m = /^(B1-(\d{2,3})-(\d)-([0-9a-z._]*))-([0-9a-z]{3})$/.exec(s);
if (!m || hashStr(m[1]) !== m[5]) return null;
const bpm = clamp(Math.round(+m[2] / 5) * 5, 90, 180), style = clamp(+m[3], 0, STYLES.length - 1);
const objs = [], seen = new Set();
if (m[4]) {
const list = m[4].split('_');
if (list.length > ED_MAX_OBJ) return null;
for (const p of list) {
const q = /^([bszpogvfce])([0-9a-z]{1,3})\.([0-8])([0-3])$/.exec(p);
if (!q) return null;
const x = parseInt(q[2], 36), y = +q[3];
if (!(x >= 0 && x <= ED_MAX_X)) return null;
const key = x * 16 + y;
if (seen.has(key)) continue;
seen.add(key);
const t = CH_TYPE[q[1]];
objs.push({ t: t, x: x, y: y, r: sanitizeR(t, +q[4]) });
}
}
return { bpm: bpm, style: style, objs: objs };
}

function mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }
