const i = pN++;
pX[i] = x; pY[i] = y; pVX[i] = vx; pVY[i] = vy; pL[i] = life; pM[i] = life; pS[i] = size; pC[i] = col; pK[i] = kind; pR[i] = Math.random() * TAU;
