ctx.beginPath();
for (const o of visB) blockPath(ctx, (o.x - camX) * U, GROUND_Y - (o.y + 1) * U);
ctx.fillStyle = pal.fill; ctx.fill();
ctx.lineWidth = 2; ctx.strokeStyle = pal.prim; ctx.stroke();
