const s = isTouch && h.touch ? h.touch : h.text;
ctx.save();
ctx.font = font(18, FONT_B, '800');
const w = ctx.measureText(s).width;
ctx.globalAlpha = 0.9;
roundRectPath(ctx, sx - 12, CEIL_Y + 22, w + 24, 34, 12);
ctx.fillStyle = 'rgba(6, 8, 16, 0.72)'; ctx.fill();
ctx.lineWidth = 1.5; ctx.strokeStyle = pal.prim; ctx.stroke();
txt(ctx, s, sx, CEIL_Y + 40, 18, FONT_B, '#ffffff', 'left', 0, '800');
ctx.restore();
