if (on) { roundRectPath(ctx, SLOT_PX + 14, y - 22, SLOT_PW - 28, 44, 10); ctx.fillStyle = 'rgba(255, 201, 60, 0.1)'; ctx.fill(); }
txt(ctx, 'Slot ' + (i + 1), SLOT_PX + 28, y, 16, FONT_B, on ? UI.hi : UI.head, 'left', 70, '800');
