const FM = '"JetBrains Mono", ui-monospace, monospace';
const C_HEAD = '#FFFFFF', C_BODY = '#C9D3E3', C_HI = '#FFC93C', C_BAD = '#FF5D5D', C_OK = '#4BE3A0';
