S[O_P] = L.entry; S[O_DNODE] = -1; S[O_TRACE] = Math.max(0, Math.min(99, L.tr0));
for (let k = 0; k < 6; k++) S[O_PROG + k] = L.prog[k];
for (let i = 0; i < L.n; i++) S[O_NODE + i] = L.type[i] === T_F ? NF_FW : 0;
for (let g = 0; g < L.nG; g++) S[L.oG + g] = L.ginit[g];
