const o = L.oE + j * ES, e = L.en[j];
S[o + E_KIND] = j < L.nE ? e.k : 0;
S[o + E_POS] = j < L.nE ? e.home : -1;
S[o + E_TGT] = -1; S[o + E_SEEN] = -1;
