const parts = [], rings = [], floats = [];
for (let i = 0; i < MAX_PARTS; i++) parts.push({ on: false, x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1, col: C_LINK, s: 2 });
for (let i = 0; i < MAX_RINGS; i++) rings.push({ on: false, x: 0, y: 0, r: 0, vr: 0, life: 0, max: 1, col: C_LINK, w: 2 });
