if (type === 'cache') { sfxCache(); burst(nodeX[a], nodeY[a], 18, C_CACHE, 150, 3); ring(nodeX[a], nodeY[a], 8, 90, C_CACHE, 0.5, 2); logAdd('+ cache pulled ' + T[O_CACHE] + '/' + L.nCache, C_CACHE); floater(nodeX[a], nodeY[a] - 20, '+DATA', C_CACHE); return; }
if (type === 'honey') { sfxHoney(); burst(nodeX[a], nodeY[a], 22, C_SEN, 170, 3); glitchT = 0.35; flash = 0.35; flashCol = C_SEN; shakeIt(5); logAdd('! HONEYPOT: trace +' + TR_HONEY, C_SEN); floater(nodeX[a], nodeY[a] - 20, 'HONEYPOT', C_SEN); return; }
if (type === 'proxy') { sfxProxy(); ring(nodeX[a], nodeY[a], 6, 140, C_PROXY, 0.7, 3); logAdd('+ proxy: trace -' + TR_PROXY, C_PROXY); floater(nodeX[a], nodeY[a] - 20, 'TRACE -' + TR_PROXY, C_PROXY); return; }
if (type === 'cipher') {
sfxCipher(); ring(nodeX[a], nodeY[a], 8, 260, C_CIPH, 0.9, 3); logAdd('+ cipher: firewalls down', C_CIPH);
for (let i = 0; i < L.n; i++) if (L.type[i] === T_F && (S[O_NODE + i] & NF_FW)) burst(nodeX[i], nodeY[i], 14, C_FW, 130, 3);
return;
}
if (type === 'frag') { sfxCache(); burst(nodeX[a], nodeY[a], 12, C_CIPH, 120, 2.5); logAdd('+ key fragment taken', C_CIPH); return; }
if (type === 'unlock') { sfxSwitch(); ring(nodeX[a], nodeY[a], 6, 100, C_LOCK, 0.5, 2); logAdd('+ lock opened', C_LOCK); return; }
if (type === 'switch') { sfxSwitch(); ring(nodeX[a], nodeY[a], 6, 120, C_SW, 0.5, 2); logAdd('~ gates flipped', C_SW); netDirty = true; return; }
if (type === 'relay') { sfxRelay(); ring(nodeX[a], nodeY[a], 4, 160, C_REL, 0.6, 3); ring(nodeX[b], nodeY[b], 30, -40, C_REL, 0.5, 2); logAdd('~ relay jump: trace +' + TR_RELAY, C_REL); return; }
if (type === 'core') { sfxCore(); burst(nodeX[a], nodeY[a], 30, C_CORE, 200, 3.5); ring(nodeX[a], nodeY[a], 10, 220, C_CORE, 0.9, 4); flash = 0.3; flashCol = C_CORE; logAdd('+ CORE TAKEN: get out!', C_CORE); floater(nodeX[a], nodeY[a] - 24, 'EXFIL', C_CORE); return; }
if (type === 'win') { logAdd('## BREACH COMPLETE ##', C_OK); return; }
if (type === 'traced') { logAdd('!! TRACED BY ' + KIND_NAME[L.en[a] ? (T[L.oE + a * ES + E_KIND] || L.en[a].k) : 1], C_SEN); return; }
if (type === 'spot') { sfxSpot(); logAdd('! hunter locked your trail', C_HUN); return; }
if (type === 'lockdown') { sfxLock(); glitchT = 0.6; flash = 0.5; flashCol = C_SEN; shakeIt(7); logAdd('!! LOCKDOWN: hunter on goal', C_SEN); say('LOCKDOWN: every hunter knows where you are', C_SEN); return; }
if (type === 'prog') {
sfxProg(a); logAdd('> run ' + PROGS[a].name.toLowerCase(), PROGS[a].col);
const px = nodeX[T[O_P]], py = nodeY[T[O_P]];
ring(px, py, 6, 120, PROGS[a].col, 0.6, 3);
if (a === P_DECOY) { ring(nodeX[b], nodeY[b], 4, 120, C_DECOY, 0.8, 3); burst(nodeX[b], nodeY[b], 14, C_DECOY, 120, 2.5); }
if (a === P_PING) { ring(px, py, 10, 520, C_SCN, 1.0, 2); }
return;
}
