isFree = false; lvIdx = i; selIdx = i; selFree = false; genPending = false; nextGenL = null;
L = levelAt(i); S = initState(L);
logClear();
logAdd('> link up: ' + SECTORS[(i / 10) | 0].name.toLowerCase(), C_DIM);
logAdd('> target: ' + L.name.toLowerCase(), C_LINK);
logAdd('> par ' + L.par + ' turns', C_DIM);
