function grade(v, th, lower) {
const better = function (a, b) { return lower ? a <= b : a >= b; };
let medal = 0;
for (let i = 0; i < 3; i++) if (better(v, th[i])) medal = i + 1;
let lo, hi;
if (medal === 0) { lo = lower ? th[0] * 1.8 : 0; hi = th[0]; }
else if (medal < 3) { lo = th[medal - 1]; hi = th[medal]; }
else { lo = th[2]; hi = lower ? th[2] * 0.8 : th[2] * 1.25; }
const perf = hi === lo ? 1 : clamp((v - lo) / (hi - lo), 0, 1);
const bases = [100, 400, 600, 800], spans = [299, 199, 199, 200];
return { medal: medal, score: Math.min(1000, Math.round(bases[medal] + spans[medal] * (isFinite(perf) ? perf : 0))) };
}

