spawnDebris(e.p.x, e.p.y, e.p.z, big ? 12 : 7, big ? 18 : 13, e.kind === 1 ? 0x5c4b3c : e.kind === 2 ? 0x6b5a48 : 0x4a505b, big ? 1.4 : 0.9, 0.35);
