tr.pos[o + 3] = tr.sp[k3] - tr.su[k3] * w; tr.pos[o + 4] = tr.sp[k3 + 1] - tr.su[k3 + 1] * w; tr.pos[o + 5] = tr.sp[k3 + 2] - tr.su[k3 + 2] * w;
