const labels = ['RESUME', 'RESTART', run && run.kind === 'swarm' ? 'QUIT TO MENU' : 'QUIT TO MISSIONS'];
for (let i = 0; i < 3; i++) button(ctx, 'p' + i, labels[i], x + 60, y + 104 + i * 56, w - 120, 46, pauseSel === i);
