function eventOpen(S,i){if(i===0)return true;const lg=Math.floor(i/6),loc=i%6;if(lg>0&&!won(S,lg*6-1))return false;if(loc===5){for(let q=lg*6;q<lg*6+5;q++)if(!won(S,q))return false;return true;}
return won(S,i-1)||won(S,i);}
function leagueOpen(S,lg){return lg===0||won(S,lg*6-1);}
function curLeague(S){let lg=0;for(let q=1;q<4;q++)if(leagueOpen(S,q))lg=q;return lg;}
function nextEvent(S){for(let i=0;i<24;i++)if(eventOpen(S,i)&&!won(S,i))return i;return 23;}
function partUnlocked(S,t){const u=PARTS[t].un;if(u==='S')return true;if(u.indexOf('SP')===0)return S.sp[+u[2]][0]>=4;return won(S,UNI[u]);}
function lockText(t){const u=PARTS[t].un;if(u.indexOf('SP')===0)return'Finish every '+SPONSORS[+u[2]].n+' contract';return'Win '+EVENTS[UNI[u]].n.replace('CHAMPION: ','')+' to unlock';}
function owns(S,t){return S.own[t]==='1';}
function medalCount(S,bit){let n=0;for(let i=0;i<24;i++)if(medals(S,i)&bit)n++;return n;}
function totalMedals(S){let n=0;for(let i=0;i<24;i++){const m=medals(S,i);n+=(m&1)+(m>>1&1)+(m>>2&1);}return n;}
function paintOpen(S,i){if(i<10)return true;if(i<22)return silverPlus(S)>=(i-9)*3;if(i===22)return S.gt>=10;return won(S,23);}
function silverPlus(S){let n=0;for(let i=0;i<24;i++){const m=medals(S,i);n+=(m>>1&1)+(m>>2&1);}return n;}
function paintRule(i){return i<22?'Earn '+(i-9)*3+' silver or gold medals':i===22?'Reach Gauntlet wave 10':'Beat Monolith Zero';}
function decalOpen(S,i){if(i<=6)return true;if(i===7)return medalCount(S,4)>=10;if(i===8)return medalCount(S,4)>=20;if(i<=12)return S.sp[i-9][0]>=2;if(i===13)return won(S,23);return S.gt>=10;}
function decalRule(i){if(i===7)return'Earn 10 gold medals';if(i===8)return'Earn 20 gold medals';if(i<=12)return'Second '+SPONSORS[i-9].n+' contract';return i===13?'Beat Monolith Zero':'Reach Gauntlet wave 10';}
function templateList(S){const out=[],need=[-1,3,2,2,5,5];for(let i=0;i<TEMPLATES.length;i++)out.push({n:TEMPLATES[i].name,bp:templateBP(i),open:need[i]<0||won(S,need[i]),rule:need[i]<0?'':'Win '+EVENTS[need[i]].n.replace('CHAMPION: ',''),rival:-1});for(let i=0;i<24;i++)out.push({n:RIVALS[i].name,bp:null,ri:i,open:S.beat[i]==='1',rule:'Beat '+RIVALS[i].name,rival:i});return out;}
function ladder(S){let rank=1;for(let i=0;i<24;i++)if(RIVALS[i].fame>S.fame)rank++;let title='Rookie';for(let i=0;i<TITLES.length;i++)if(rank<=TITLES[i][0])title=TITLES[i][1];if(S.fame>=10000)title='Legend';return{rank:rank,title:title};}
const DIFFM=[0.75,1,1.25];function gauntletRival(wave,rng){if(wave===4)return 5;if(wave===8)return 11;if(wave===12)return 17;if(wave===16)return 23;const lg=wave<=3?0:wave<=7?1:wave<=11?2:3;return lg*6+Math.floor(rng()*5);}
