const damp = 1 - 2.5 * dt;
for (let i = 0; i < particles.length; i++) {
const p = particles[i];
p.life -= dt;
if (p.life <= 0) continue;
p.vx *= damp; p.vy = p.vy * damp + p.g * dt;
p.x += p.vx * dt; p.y += p.vy * dt;
particles[j++] = p;
}
particles.length = j;
j = 0;
for (let i = 0; i < popups.length; i++) { const p = popups[i]; p.t += dt; if (p.t < p.life) popups[j++] = p; }
popups.length = j;
j = 0;
for (let i = 0; i < beams.length; i++) { const b = beams[i]; b.t -= dt; if (b.t > 0) beams[j++] = b; }
beams.length = j;
if (shakeT > 0) shakeT = Math.max(0, shakeT - dt);
if (hurtT > 0) hurtT = Math.max(0, hurtT - dt);
const k = Math.min(1, dt * 12);
for (let i = 0; i < N; i++) light[i] += (lightT[i] - light[i]) * k;
hpShown += (hero.hp - hpShown) * Math.min(1, dt * 12);
