function loadTrick(S, T) {
clearSim(S, 16);
const lim = function (v, m) { return clamp(v, -m, m); };
placeBall(S, 0, lim(T.c[0] * DIA, HL - R - 0.001), lim(T.c[1] * DIA, HW - R - 0.001));
for (let i = 0; i < T.b.length; i++) {
const b = T.b[i];
placeBall(S, b[0], lim(b[1] * DIA, HL - R - 0.0005), lim(b[2] * DIA, HW - R - 0.0005));
if (Math.abs(b[2]) > 1.92 || Math.abs(b[1]) > 3.82 && Math.abs(b[2]) > 1.8) { S.x[b[0]] = b[1] * DIA; S.z[b[0]] = b[2] * DIA; }
}
for (let pass = 0; pass < 4; pass++) {
for (let i = 0; i < 16; i++) {
if (!S.on[i]) continue;
for (let j = i + 1; j < 16; j++) {
if (!S.on[j]) continue;
const dx = S.x[j] - S.x[i], dz = S.z[j] - S.z[i], d = Math.sqrt(dx * dx + dz * dz), need = TWO_R + 0.00012;
if (d < need && d > 1e-6) { const p = (need - d) / 2; S.x[i] -= dx / d * p; S.z[i] -= dz / d * p; S.x[j] += dx / d * p; S.z[j] += dz / d * p; }
}
}
}
}
function trickDone(T, S) {
for (let k = 0; k < S.potN; k++) if (S.potList[k] === 0) return false;
for (let i = 0; i < T.t.length; i++) {
const b = T.t[i];
if (S.on[b]) return false;
if (T.r && S.rc[b] < T.r) return false;
}
if (T.k && S.cuePre < T.k) return false;
return true;
}

function thumbBall(ctx, x, y, r, hex, stripe, num) {
ctx.fillStyle = 'rgba(0,0,0,0.45)';
ctx.beginPath(); ctx.ellipse(x + r * 0.25, y + r * 0.85, r * 1.05, r * 0.38, 0, 0, TAU); ctx.fill();
ctx.save();
ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.clip();
ctx.fillStyle = stripe ? '#f1ece0' : hexCss(hex); ctx.fillRect(x - r, y - r, r * 2, r * 2);
if (stripe) { ctx.fillStyle = hexCss(hex); ctx.fillRect(x - r, y - r * 0.45, r * 2, r * 0.9); }
if (num) {
ctx.fillStyle = '#f6f2e8'; ctx.beginPath(); ctx.arc(x - r * 0.12, y - r * 0.08, r * 0.42, 0, TAU); ctx.fill();
ctx.fillStyle = '#151515'; ctx.font = 'bold ' + Math.round(r * 0.55) + 'px ' + FONT_B; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
ctx.fillText(String(num), x - r * 0.12, y - r * 0.05);
}
const g = ctx.createRadialGradient(x - r * 0.4, y - r * 0.45, r * 0.05, x, y, r * 1.05);
g.addColorStop(0, 'rgba(255,255,255,0.75)'); g.addColorStop(0.25, 'rgba(255,255,255,0.08)'); g.addColorStop(0.7, 'rgba(0,0,0,0.05)'); g.addColorStop(1, 'rgba(0,0,0,0.55)');
ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2);
ctx.restore();
}
