const AI = { jobs: [], evals: [], cands: [], K: 1, ri: 0, ji: 0, vi: 0, best: null, bestEV: -1e9, t: 0, stage: '', L: null, sigma: 0.01, style: 'plain', minT: 0.8, from: 0, to: 0, dur: 0.6, placeFrom: [0, 0], placeTo: [0, 0], placeT: 0 };
