AI.stage = 'think';
const spins = AI.style === 'spin' || P.lvl >= 3 ? [[0, 0], [0, 0.6], [0, -0.7], [0.45, 0.3], [-0.45, 0.3]] : [[0, 0], [0, 0.55], [0, -0.6]];
