for (let k = 0; k < tmpList.length; k++) AI.jobs.push({ kind: 'kick', ang: Math.atan2(S.z[tmpList[k]] - cz, S.x[tmpList[k]] - cx), v0: 2.2, a: 0, b: 0, pk: -1, p: 0.6 });
