if (focus === n - 1) { if (up) focus = nc - 1; else return up || down; }
else if (left && focus >= nc) focus = Math.min(nc - 1, focus - nc);
else if (right && focus < nc) focus = Math.min(n - 2, focus + nc);
else if (up) focus = focus === 0 || focus === nc ? focus : focus - 1;
