function prepRig(rig) { // each bone's subtree (itself plus descendants); parents always precede children
for (let i = 0; i < rig.length; i++) {
const sub = [i];
for (let j = i + 1; j < rig.length; j++) {
let p = rig[j].p;
while (p >= 0 && p !== i) p = rig[p].p;
if (p === i) sub.push(j);
}
rig[i].sub = sub;
}
}
