ctx.fillStyle = rnd() < 0.7 ? 'rgba(255, 190, 120, 0.55)' : 'rgba(120, 220, 255, 0.6)';
ctx.fillRect((bx + 0.006 + (k % 3) * bw * 0.3) * w, (top + 0.02 + Math.floor(k / 3) * 0.035) * h, Math.max(1, w * 0.006), Math.max(1, h * 0.012));
