slab(-hw, hw, -hw, hw, cy);
edgeX(-hw, -hw, hw, cy, 0.6); edgeX(hw, -hw, hw, cy, 0.6); edgeZ(-hw, -hw, hw, cy, 0.6); edgeZ(hw, -hw, hw, cy, 0.6);
