function groundAt(x, z, yTop) {
let best = -1e9;
const bs = L.boxes;
for (let i = 0; i < bs.length; i++) {
const b = bs[i];
if (!b.on || x < b.x0 || x > b.x1 || z < b.z0 || z > b.z1) continue;
if (b.y1 <= yTop && b.y1 > best) best = b.y1;
}
return best;
}
function rayBoxes(ox, oy, oz, dx, dy, dz, maxT) { // nearest hit along a ray (camera collision); gates are ignored
let best = maxT;
for (let li = 0; li < 2; li++) {
const bs = li ? L.camBoxes : L.boxes;
for (let i = 0; i < bs.length; i++) {
const b = bs[i];
if (b.gate >= 0) continue;
let t0 = 0, t1 = best;
if (Math.abs(dx) < 1e-6) { if (ox < b.x0 || ox > b.x1) continue; }
else { let ta = (b.x0 - ox) / dx, tb = (b.x1 - ox) / dx; if (ta > tb) { const t = ta; ta = tb; tb = t; } if (ta > t0) t0 = ta; if (tb < t1) t1 = tb; if (t0 > t1) continue; }
if (Math.abs(dy) < 1e-6) { if (oy < b.y0 || oy > b.y1) continue; }
else { let ta = (b.y0 - oy) / dy, tb = (b.y1 - oy) / dy; if (ta > tb) { const t = ta; ta = tb; tb = t; } if (ta > t0) t0 = ta; if (tb < t1) t1 = tb; if (t0 > t1) continue; }
if (Math.abs(dz) < 1e-6) { if (oz < b.z0 || oz > b.z1) continue; }
else { let ta = (b.z0 - oz) / dz, tb = (b.z1 - oz) / dz; if (ta > tb) { const t = ta; ta = tb; tb = t; } if (ta > t0) t0 = ta; if (tb < t1) t1 = tb; if (t0 > t1) continue; }
if (t0 > 0.001 && t0 < best) best = t0;
}
}
return best;
}

