b.wt[0] = w0; b.wt[1] = w1; b.wt[2] = w2; b.wt[3] = w3;
for (let i = 0; i < NB; i++) { b.has[i] = 0; b.cut[i] = 0; b.geo[i] = -1; b.gl[i] = -1; b.rx[i] = 0; b.ry[i] = 0; b.rz[i] = 0; b.leak[i] = 0; }
