const i = ptN++, i3 = i * 3;
ptPos[i3] = x; ptPos[i3 + 1] = y; ptPos[i3 + 2] = z;
ptVel[i3] = vx; ptVel[i3 + 1] = vy; ptVel[i3 + 2] = vz;
ptBase[i3] = r; ptBase[i3 + 1] = g; ptBase[i3 + 2] = b;
ptCol[i3] = r; ptCol[i3 + 1] = g; ptCol[i3 + 2] = b;
