const i3 = i * 3, l3 = last * 3;
for (let k = 0; k < 3; k++) { ptPos[i3 + k] = ptPos[l3 + k]; ptVel[i3 + k] = ptVel[l3 + k]; ptBase[i3 + k] = ptBase[l3 + k]; ptCol[i3 + k] = ptCol[l3 + k]; }
ptLife[i] = ptLife[last]; ptMax[i] = ptMax[last]; ptKind[i] = ptKind[last]; ptFloor[i] = ptFloor[last]; ptSz0[i] = ptSz0[last]; ptSize[i] = ptSize[last];
