function drawHUD() {
ctx.setTransform(1, 0, 0, 1, 0, 0);
ctx.clearRect(0, 0, hud.width, hud.height);
if (mode === 'title') { drawTitle(); return; }
drawWorldMarks();
if (P.focusing) drawFocusOverlay();
drawPlayHUD();
if (whiteFlash > 0 || hurtFlash > 0 || (P.hp < 30 && mode === 'playing')) {
ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
if (whiteFlash > 0) { ctx.fillStyle = 'rgba(210,255,255,' + (whiteFlash * 0.3).toFixed(3) + ')'; ctx.fillRect(0, 0, view.w, view.h); }
if (hurtFlash > 0) { // signal glitch, not gore: shifted scan bands
ctx.fillStyle = 'rgba(255,60,140,' + (hurtFlash * 0.18).toFixed(3) + ')';
for (let k = 0; k < 5; k++) ctx.fillRect(0, Math.random() * view.h, view.w, 4 + Math.random() * 18);
ctx.fillStyle = 'rgba(92,242,255,' + (hurtFlash * 0.12).toFixed(3) + ')';
for (let k = 0; k < 3; k++) ctx.fillRect(0, Math.random() * view.h, view.w, 2 + Math.random() * 10);
}
const low = P.hp < 30 && mode === 'playing' ? (0.25 + 0.2 * Math.sin(animT * 6)) : 0;
const a = Math.max(low, hurtFlash * 0.5);
if (a > 0.01) { ctx.strokeStyle = 'rgba(255,70,150,' + a.toFixed(3) + ')'; ctx.lineWidth = 34 * view.s; ctx.strokeRect(0, 0, view.w, view.h); }
}
drawBannerHint();
if (touchUI && mode === 'playing' && !paused) drawTouch();
if (paused) drawPause();
else if (mode === 'over') drawOver();
}

function tone(f, d, o) { try { api.tone(f, d, o); } catch (err) { /* sound is optional */ } }
function noise(d, o) { try { api.noise(d, o); } catch (err) { /* sound is optional */ } }
let sfxGate = 0; // caps how many effects start in one frame
function sfxOk() { if (sfxGate > 6) return false; sfxGate++; return true; }
function sfxSwing(heavy) { if (!sfxOk()) return; noise(heavy ? 0.16 : 0.09, { vol: heavy ? 0.12 : 0.08, filter: heavy ? 1800 : 3200 }); tone(heavy ? 300 : 520, 0.06, { type: 'sine', vol: 0.03, slide: heavy ? 140 : 260 }); }
function sfxHit(heavy) { if (!sfxOk()) return; noise(0.07, { vol: 0.12, filter: 2400 }); tone(heavy ? 160 : 240, 0.08, { type: 'square', vol: 0.05, slide: 90 }); }
function sfxSever(big) { if (!sfxOk()) return; tone(big ? 1400 : 1800, 0.12, { type: 'sawtooth', vol: 0.045, slide: big ? 300 : 600 }); noise(0.18, { vol: 0.1, filter: 5000 }); tone(2600, 0.05, { type: 'sine', vol: 0.035, delay: 0.03 }); }
function sfxKill() { if (!sfxOk()) return; const r = S.rank; tone(440 + r * 60, 0.08, { type: 'triangle', vol: 0.06 }); tone(660 + r * 90, 0.1, { type: 'triangle', vol: 0.05, delay: 0.06 }); }
function sfxClang() { if (!sfxOk()) return; tone(1250, 0.12, { type: 'square', vol: 0.045, slide: 900 }); tone(1870, 0.1, { type: 'sine', vol: 0.04 }); noise(0.05, { vol: 0.06, filter: 4000 }); }
function sfxClank(s) { if (!sfxOk()) return; tone(300 + Math.random() * 200, 0.05, { type: 'square', vol: 0.025 * Math.min(2, s), slide: 180 }); }
function sfxParry() { tone(1900, 0.18, { type: 'sine', vol: 0.08 }); tone(2850, 0.22, { type: 'sine', vol: 0.05, delay: 0.02 }); noise(0.05, { vol: 0.08, filter: 6000 }); }
function sfxParryUp() { tone(900, 0.04, { type: 'triangle', vol: 0.03, slide: 1300 }); }
function sfxDeflect(perfect) { if (!sfxOk()) return; tone(perfect ? 2200 : 1500, 0.12, { type: 'sine', vol: 0.07, slide: perfect ? 3000 : 1900 }); }
function sfxHurt() { tone(140, 0.2, { type: 'sawtooth', vol: 0.09, slide: 60 }); noise(0.12, { vol: 0.1, filter: 900 }); }
function sfxDeath() { tone(300, 0.9, { type: 'sawtooth', vol: 0.08, slide: 40 }); noise(0.5, { vol: 0.08, filter: 600 }); }
function sfxDash() { if (!sfxOk()) return; noise(0.12, { vol: 0.07, filter: 2600 }); }
function sfxJump(k) { tone(k === 2 ? 520 : (k ? 660 : 420), 0.07, { type: 'triangle', vol: 0.04, slide: k ? 980 : 640 }); }
function sfxLand() { if (!sfxOk()) return; noise(0.05, { vol: 0.05, filter: 700 }); }
function sfxSlam() { noise(0.3, { vol: 0.16, filter: 500 }); tone(90, 0.25, { type: 'sine', vol: 0.1, slide: 40 }); }
function sfxBoom() { if (!sfxOk()) return; noise(0.25, { vol: 0.12, filter: 700 }); }
function sfxDeny() { tone(180, 0.1, { type: 'square', vol: 0.04 }); }
function sfxFocusIn() { tone(600, 0.35, { type: 'sine', vol: 0.06, slide: 150 }); noise(0.3, { vol: 0.04, filter: 400 }); }
function sfxFocusCut(n) { noise(0.35, { vol: 0.16, filter: 5200 }); tone(2400, 0.3, { type: 'sawtooth', vol: 0.045, slide: 200 }); if (n) tone(180, 0.4, { type: 'sine', vol: 0.1, slide: 60, delay: 0.05 }); }
function sfxRank(r) { tone(500 + r * 110, 0.1, { type: 'triangle', vol: 0.05 }); tone(750 + r * 160, 0.14, { type: 'triangle', vol: 0.045, delay: 0.07 }); }
function sfxWindup(big) { if (!sfxOk()) return; tone(big ? 220 : 380, big ? 0.4 : 0.22, { type: 'sawtooth', vol: big ? 0.05 : 0.03, slide: big ? 520 : 760 }); }
function sfxCharge() { if (!sfxOk()) return; tone(500, 0.3, { type: 'sine', vol: 0.03, slide: 1400 }); }
function sfxShoot(s) { if (!sfxOk()) return; tone(s > 1.2 ? 260 : 420, 0.12, { type: 'square', vol: 0.04, slide: s > 1.2 ? 120 : 200 }); }
function sfxEngage() { tone(330, 0.12, { type: 'square', vol: 0.04 }); tone(440, 0.16, { type: 'square', vol: 0.04, delay: 0.1 }); }
function sfxClear() { tone(523, 0.1, { type: 'triangle', vol: 0.06 }); tone(659, 0.1, { type: 'triangle', vol: 0.06, delay: 0.09 }); tone(784, 0.2, { type: 'triangle', vol: 0.06, delay: 0.18 }); }
function sfxBossIntro() { tone(110, 0.8, { type: 'sawtooth', vol: 0.07, slide: 55 }); noise(0.6, { vol: 0.06, filter: 300 }); }
function sfxBossPhase() { tone(220, 0.5, { type: 'sawtooth', vol: 0.06, slide: 440 }); }
function sfxBossDown() { noise(0.8, { vol: 0.16, filter: 900 }); tone(80, 1, { type: 'sine', vol: 0.12, slide: 30 }); }
function sfxStageClear() { const n = [523, 659, 784, 1047]; for (let i = 0; i < n.length; i++) tone(n[i], 0.18, { type: 'triangle', vol: 0.06, delay: i * 0.11 }); }
function sfxThunder() { noise(1.2, { vol: 0.1, filter: 300, delay: 0.3 }); }
function sfxTick() { tone(1200, 0.03, { type: 'square', vol: 0.03 }); }

let amb = null, noiseBuf = null, noiseCtx = null, ambPollT = 0, beatT = 0, beatI = 0, ambCtlT = 0;
const ARP = [0, 7, 12, 15, 19, 15, 12, 7];
const ROOTS = [55, 55, 49, 43.65];
function stopAmbience() {
if (!amb) return;
const nodes = amb.nodes;
amb = null;
for (let i = 0; i < nodes.length; i++) {
const n = nodes[i];
try { if (typeof n.stop === 'function') n.stop(); } catch (err) { /* already stopped */ }
try { n.disconnect(); } catch (err) { /* already disconnected */ }
}
}
function startAmbience() {
stopAmbience();
if (mode !== 'playing' || paused || destroyed) return;
let a = null;
try { a = api.audio ? api.audio() : null; } catch (err) { a = null; }
if (!a || !a.ctx || !a.out) return;
const ac = a.ctx;
amb = { ctx: ac, nodes: [], bassO: null, bassF: null, arpO: null, arpG: null, shimG: null };
const nodes = amb.nodes;
function N(n) { nodes.push(n); return n; }
try {
if (noiseCtx !== ac) {
const len = Math.floor(ac.sampleRate * 2);
noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
const d = noiseBuf.getChannelData(0);
for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
noiseCtx = ac;
}
const src = N(ac.createBufferSource()); src.buffer = noiseBuf; src.loop = true; // high wind between the towers
const wf = N(ac.createBiquadFilter()); wf.type = 'bandpass'; wf.frequency.value = L.theme.rain ? 1200 : 480; wf.Q.value = 0.7;
const wg = N(ac.createGain()); wg.gain.value = L.theme.rain ? 0.035 : 0.022;
src.connect(wf); wf.connect(wg); wg.connect(a.out);
const bass = N(ac.createOscillator()); bass.type = 'sawtooth'; bass.frequency.value = 55;
const bf = N(ac.createBiquadFilter()); bf.type = 'lowpass'; bf.frequency.value = 220; bf.Q.value = 5;
const bg = N(ac.createGain()); bg.gain.value = 0.03;
const lfo = N(ac.createOscillator()); lfo.type = 'sine'; lfo.frequency.value = 132 / 60; // pulses on the beat
const lg = N(ac.createGain()); lg.gain.value = 120;
lfo.connect(lg); lg.connect(bf.frequency);
bass.connect(bf); bf.connect(bg); bg.connect(a.out);
const arp = N(ac.createOscillator()); arp.type = 'square'; arp.frequency.value = 220;
const af = N(ac.createBiquadFilter()); af.type = 'lowpass'; af.frequency.value = 1500;
const ag = N(ac.createGain()); ag.gain.value = 0;
arp.connect(af); af.connect(ag); ag.connect(a.out);
const pad1 = N(ac.createOscillator()); pad1.type = 'triangle'; pad1.frequency.value = 110;
const pad2 = N(ac.createOscillator()); pad2.type = 'triangle'; pad2.frequency.value = 110.7;
const pg = N(ac.createGain()); pg.gain.value = 0.01;
pad1.connect(pg); pad2.connect(pg); pg.connect(a.out);
const shim = N(ac.createOscillator()); shim.type = 'sine'; shim.frequency.value = 1760;
const sg = N(ac.createGain()); sg.gain.value = 0;
shim.connect(sg); sg.connect(a.out);
src.start(); bass.start(); lfo.start(); arp.start(); pad1.start(); pad2.start(); shim.start();
amb.bassO = bass; amb.bassF = bf; amb.arpO = arp; amb.arpG = ag; amb.shimG = sg;
beatT = 0; beatI = 0;
} catch (err) { stopAmbience(); }
}
function updateAmbience(rdt) {
ambPollT -= rdt;
if (ambPollT <= 0) { // sound may have been switched on or off in the hub
ambPollT = 1.5;
let a = null;
try { a = api.audio ? api.audio() : null; } catch (err) { a = null; }
if (!amb && a) startAmbience();
else if (amb && (!a || a.ctx !== amb.ctx)) { stopAmbience(); if (a) startAmbience(); }
}
if (!amb) return;
const stepLen = 60 / 132 / 2;
beatT += rdt * (P.focusing ? 0.25 : 1);
try {
const t = amb.ctx.currentTime;
if (beatT >= stepLen) {
beatT = beatT - stepLen > stepLen ? 0 : beatT - stepLen;
beatI = (beatI + 1) % 64;
const root = ROOTS[Math.floor(beatI / 16) % 4];
const play = S.rank >= 1 || boss || beatI % 2 === 0;
const lvl = play ? (0.008 + S.rank * 0.0028) * (P.focusing ? 0.4 : 1) * (boss ? 1.3 : 1) : 0;
amb.arpO.frequency.setValueAtTime(root * 2 * Math.pow(2, ARP[beatI % 8] / 12), t);
amb.arpG.gain.cancelScheduledValues(t);
amb.arpG.gain.setValueAtTime(lvl, t);
amb.arpG.gain.setTargetAtTime(0, t + 0.02, 0.05);
if (beatI % 16 === 0) amb.bassO.frequency.setTargetAtTime(root, t, 0.02);
}
ambCtlT -= rdt;
if (ambCtlT <= 0) {
ambCtlT = 0.12;
amb.bassF.frequency.setTargetAtTime((P.focusing ? 120 : 180 + S.rank * 55 + (boss ? 120 : 0)), t, 0.2);
amb.shimG.gain.setTargetAtTime(P.focusing ? 0.018 : 0, t, 0.1);
}
} catch (err) { /* context closed */ }
}

const keys = {};
let stick = null, lookTouch = null, drag = null, pausedAt = 0;
const tbtn = { slash: -1, heavy: -1, parry: -1, dash: -1, jump: -1, focus: -1, lock: -1 };
const fcur = { x: 140, y: 0 };
function clearInput() {
for (const k in keys) keys[k] = false;
stick = null; lookTouch = null; drag = null;
for (const k in tbtn) tbtn[k] = -1;
P.lightBuf = 0; P.heavyBuf = 0; P.parryBuf = 0; P.dashBuf = 0; P.jumpBuf = 0;
if (P.focusing) { P.focusing = false; clearPreview(); }
}
function getMove(out) {
let x = 0, y = 0;
if (keys.KeyA) x -= 1;
if (keys.KeyD) x += 1;
if (keys.KeyW) y += 1;
if (keys.KeyS) y -= 1;
if (stick) { x += stick.vx; y += stick.vy; }
const m = Math.hypot(x, y);
if (m > 1) { x /= m; y /= m; }
out.x = x; out.y = y;
return out;
}
