let CH=[{n:'COLD OPEN',sec:'Habitat Ring',th:0,par:540,goal:'Restore emergency power and get the service lift running.',nh:'Your lamp, your Sounder, and somewhere to hide.',radio:"You're in. The ring's dark. Get me power and I'll get you out.",lay:['Y.Q.O..','=.|.=..','+-+1R2H','....2..','M-+-+3Y'],pw:['000.','d11u','0000'],all:3,chal:['Unseen','Its awareness of you never reaches full.'],kit:{lamp:70,on:0},it:[[0,0,1,'n',0],[0,0,2,'Y',0],[0,0,[1,6],'L',[1,0,0,0]],[0,0,[1,7],'L',[0,0,0,1]],[0,1,1,'i',0,1],[1,0,1,'k','fuse'],[1,0,2,'n',1],[1,0,[1,1],'L',[0,1,0,0]],[1,0,[5,1],'L',[1,0,0,0]],[1,1,1,'F',1,1],[2,1,1,'G',3,2],[2,1,2,'n',3],[2,1,[3,1],'L',[0,0,1,0]],[2,1,[5,1],'L',[0,1,0,0]],[2,1,[1,7],'L',[1,0,0,0]],[2,1,[7,5],'L',[0,0,0,1]],[2,0,1,'n',4],[2,0,2,'b',0],[2,0,[2,2],'L',[1,0,0,0]],[2,0,[6,2],'L',[0,0,1,0]],[3,1,1,'i',1,1],[3,1,2,'n',2],[3,1,[1,6],'L',[0,1,0,0]],[1,2,1,'i',2,1],[1,2,'C','L',[1,0,0,0]],[2,2,'C','L',0],[0,2,1,'B',3],[0,2,2,'i',0,1],[3,2,2,'Y',3]],obj:[['Find power for the ring',['Follow the corridor out of the lift bay'],'m1,1'],['Restore emergency power',['Find a fuse (crew quarters)','Fuse box, east corridor'],'c1',['kfuse','c1']],['Route power in the Office',['Relay panel, Office'],'c2'],['Hide until it leaves',['Desks and lockers show E'],'sp3'],['Reach the safe room',['Safe room, east of the Office'],'m3,1'],['Pull the main breaker in the Mess',['Mess Hall, west'],'c3'],['Get the service lift running',['Lift console, east'],'end']]},{n:'SPECIMEN',sec:'Research Labs',th:1,par:780,goal:"Get the Director's uplink key from Containment, then restore lift power.",nh:'A shock baton, glassmites, keycards, and the visor shutter.',radio:'Labs next. Whatever happened down there started there. Careful.',lay:['Y=+-S.D..','..|...|..','A-+-U-+1R','..|.|...|','..Ev+bAvK','..|.|...2','..H-+...Y'],pw:['0000.','11111','.1100','.u0.0'],all:2,chal:['Archivist','Find all 5 logs in this chapter.'],kit:{lamp:100,on:0,pou:[[0,1],[1,1],[2,1]],p:[1,1,0,0]},it:[[0,0,2,'Y',0],[2,0,1,'t',0],[2,0,2,'n',5],[3,0,1,'b',1],[3,0,2,'n',9],[3,0,[1,1],'L',1],[0,1,1,'n',6],[0,1,2,'i',0,1],[0,1,'c','m',2,'sp5'],[2,1,1,'i',2,1],[3,1,'c','m',2,'c1'],[4,1,1,'k','card'],[4,1,2,'n',7],[1,2,1,'p',[1,1,0,0]],[1,2,2,'G',4,1],[1,2,'M','M','dead'],[3,2,1,'W','uplink'],[3,2,2,'n',8],[4,2,1,'b',2],[4,2,2,'B','brk','kuplink'],[4,2,'c','m',2,'sp6'],[1,3,1,'i',1,1],[1,3,2,'i',0,1],[4,3,2,'Y',2]],obj:[['Search Storage for a tool',['Storage, north'],'t0'],['Restore power to the labs',['Relay panel, Engineering'],'c1'],["Get the Director's keycard",['Office, east'],'kcard'],['Take the uplink key',['Blue door, Containment'],'kuplink'],['Escape the lockdown',['Crawl through the east vent (C)','Pull the breaker in the Server Room'],'brk',['m4,2','brk']],['Wait out the power cycle',['Lift power cycling'],'c2'],['Take the lift',['Lift console, south-east'],'end']]},{n:'GREENHOUSE',sec:'Hydroponics',th:2,par:900,goal:'Restart the air scrubbers and purge the spores.',nh:'Sporebells, the weld torch, and a valve puzzle. The purge is loud.',radio:"Air's bad below you. Fix it before you go deeper.",lay:['..G-+-G..','....|....','Y=+-U-+-H','..|.j.|..','..G.E.G..','..|......','..S-+1K2Y'],pw:['.000.','0000u','.000.','.0000'],all:2,cr:{1:'leverA&leverB'},chal:['Weed Killer','Destroy all 10 sporebells before they burst.'],kit:{lamp:100,on:0,tools:1,pou:[[0,1],[1,1],[2,1]],p:[1,1,1,0]},it:[[1,0,1,'t',2],[1,0,2,'n',12],[1,0,'c','s'],[1,0,'e','s'],[3,0,1,'n',10],[3,0,2,'B','leverA','man'],[3,0,'c','s'],[3,0,[2,2],'s'],[3,0,[6,6],'s'],[0,1,1,'i',0,1],[0,1,2,'Y',0],[2,1,1,'n',11],[2,1,2,'i',2,1],[3,1,'c','m',4,'sp7'],[4,1,1,'i',1,1],[4,1,2,'n',14],[1,2,1,'b',4],[1,2,2,'i',3,2],[1,2,'c','s'],[1,2,[2,5],'s'],[1,2,[6,2],'s'],[1,2,'c','m',2],[2,2,1,'a','f',25],[2,2,2,'p',[0,0,1,0]],[2,2,'M','M','man',0],[3,2,1,'o'],[3,2,2,'B','leverB','man'],[3,2,'c','s'],[3,2,[2,2],'s'],[1,3,1,'b',3],[1,3,2,'n',13],[3,3,1,'i',4,1],[3,3,2,'G',5,'purge'],[4,3,2,'Y',2]],obj:[['Find the weld torch',['North-west bay'],'t2'],['Get into the pump room',['Cut the jammed hub door (torch) or pry it (E)'],'jam'],['Route water to the scrubbers',['Valve manifold, pump room'],'man'],['Start both scrubbers',['Lever A, north-east bay','Lever B, south-east bay'],'c1',['leverA','leverB']],['Purge the spores',['Purge console, control room'],'purge'],['Survive the purge',['Hide or keep moving'],'c2'],['Take the lift',['Lift console, east'],'end']]},{n:'HEARTBEAT',sec:'Reactor',th:3,par:960,goal:'Wake the reactor: both backup generators, coolant, then hold it through spin-up.',nh:'Criers, the nail driver, generators that bite back, and a long spin-up.',radio:"Reactor's the big one. It's going to be loud.",lay:['Y=+-E-+-R..','..|.....|..','H-+-C=C-+-S','..x...1.|..','..E-+sK.+2Y'],pw:['00g00.','u01100','.h0100'],all:2,cr:{1:'gen0&gen1'},chal:['Steady Hands','Start both generators without a backfire.'],kit:{lamp:100,on:0,tools:5,f:60,pou:[[0,1],[1,1],[3,2]],p:[1,1,1,1]},it:[[0,0,1,'i',0,1],[0,0,2,'Y',0],[2,0,1,'i',0,1],[2,0,2,'n',16],[2,0,'M','M','gen','gen0'],[3,0,'c','c'],[4,0,1,'t',1],[4,0,2,'n',15],[4,0,[3,1],'L','n'],[0,1,1,'i',1,1],[0,1,2,'n',19],[1,1,1,'n',17],[2,1,1,'V',0],[2,1,2,'i',3,2],[2,1,2,'c'],[2,1,'c','m',2],[3,1,1,'V',1],[3,1,'c','s'],[3,1,2,'o'],[4,1,'c','c'],[5,1,1,'i',4,1],[5,1,2,'n',18],[5,1,'c','m',2],[1,2,1,'b',5],[1,2,2,'p',[2,0,0,0]],[1,2,'M','M','gen','gen1'],[1,2,'c','s'],[2,2,'c','c'],[3,2,1,'B','start','man'],[3,2,2,'M','man',1],[4,2,'c','m',2],[4,2,'e','s'],[5,2,2,'Y',2]],obj:[['Start backup generator A',['Generator A, north'],'gen0'],["Search the Chief's office",['Office, north-east'],'t1'],['Get into Generator B',['Tear the planks, west corridor (E)'],'planks'],['Start backup generator B',['Generator B, south-west'],'c1'],['Route coolant to the cores',['Coolant manifold, control room'],'man'],['Pull the start lever',['Control room'],'start'],['Hold the reactor through spin-up',['Reseat any slipped coolant valve'],'c2'],['Take the lift',['Lift console, south-east'],'end']]},{n:'LOW WATER',sec:'Flooded Lower Decks',th:4,par:1020,goal:'Restart pumps A, B and C, then reach the spire lift.',nh:'Deep water, lures on the ceiling, and a flare launcher.',radio:"Water's rising under you. Pumps first.",lay:['Y=+-H....','..|......','..+-U=+-E','..|.|.|..','E-+.S.+-K','..|...2..','..D2+-E3Y'],pw:['00u..','.1222','11222','.1333'],all:3,cr:{1:'pump0',2:'pump1',3:'pump0&pump1&pump2'},water:['000..','.1222','11222','.1333'],wl:[0,.45,.85,.85],chal:['Ghost Water','Never caught (Story: never knocked down).'],kit:{lamp:100,on:0,tools:7,f:60,n:24,mag:12,pou:[[0,1],[1,1],[3,2]],p:[0,0,0,0]},it:[[0,0,1,'i',0,1],[0,0,2,'Y',0],[2,0,1,'i',1,1],[2,0,2,'i',0,1],[1,1,'c','l'],[2,1,1,'k','fuse',0],[2,1,2,'n',21],[2,1,2,'c'],[2,1,'c','l'],[2,1,[2,6],'m',2],[3,1,'c','l'],[4,1,1,'i',3,2],[4,1,2,'p',[0,1,1,0]],[4,1,'M','M','pump',1],[0,2,1,'p',[1,0,0,0]],[0,2,2,'n',20],[0,2,'M','M','pump',0],[1,2,'c','l'],[1,2,'c','m',2],[2,2,1,'t',3],[2,2,2,'n',22],[2,2,[3,3],'s'],[2,2,[5,5],'s'],[3,2,1,'n',23],[3,2,'c','l'],[4,2,1,'k','fuse',1],[4,2,2,'b',6],[4,2,'c','c'],[4,2,'e','s'],[1,3,1,'k','fuse',2],[1,3,2,'n',24],[1,3,'e','s'],[2,3,'c','l'],[2,3,'c','m',2],[3,3,1,'i',1,1],[3,3,'M','M','pump',2],[4,3,2,'Y',3]],obj:[['Start pumps A and B',['Fuse A (hub), Pump A (west)','Fuse B (pump control), Pump B (east)'],'c1&c2',['c1','c2']],['Start pump C',['Fuse C (medbay), Pump C (south)'],'c3'],['Reach the spire lift',['Lift console, south-east'],'end']]},{n:'DEAD SIGNAL',sec:'The Spire',th:5,par:960,goal:'Clear the dish, send the signal, survive until Long Patience lands, and get on board.',nh:'Wind, the dish, and two minutes of signal. Then the pad.',radio:"That's the spire. I can see your lift lights from orbit. Almost.",lay:['Z-+-Z-+2Z','..|.|.|..','Y=+-K-+-H','..|.|.|..','Z-+-O-+-Z'],pw:['aaaaa','aaaau','aaaaa'],all:9,cr:{1:'heat0&heat1&heat2'},chal:['Last Word','Never caught (Story: never knocked down).'],kit:{lamp:100,on:0,tools:15,f:60,n:24,mag:12,pou:[[3,3],[1,2],[0,1],[4,1]],p:[0,0,0,0]},it:[[0,0,1,'i',0,1],[0,0,'M','M','heat',0],[0,0,2,'c'],[1,0,1,'R',0],[2,0,1,'n',28],[2,0,2,'i',3,3],[2,0,'M','M','dish'],[3,0,'c','l'],[4,0,1,'i',3,2],[4,0,2,'i',4,1],[4,0,'M','M','pylon'],[4,0,[7,1],'Q',0],[4,0,[7,4],'Q',1],[4,0,[7,7],'Q',2],[0,1,1,'n',25],[0,1,2,'Y',0],[1,1,1,'n',26],[2,1,1,'X',0,'tuned'],[2,1,2,'U',3,'c1'],[3,1,1,'R',1],[3,1,'c','o'],[4,1,1,'i',1,2],[4,1,2,'n',29],[0,2,1,'i',4,1],[0,2,'M','M','heat',1],[0,2,2,'c'],[1,2,1,'R',2],[1,2,'c','l'],[2,2,1,'i',1,1],[2,2,2,'n',27],[2,2,2,'o'],[3,2,'c','s'],[3,2,'e','s'],[4,2,1,'i',0,1],[4,2,'M','M','heat',2],[4,2,'c','m',4]],obj:[['Thaw the dish',['Heater, west deck','Heater, south-west deck','Heater, south-east deck'],'c1',['heat0','heat1','heat2']],['Tune the carrier',['Tuning console, transmitter room'],'tuned'],['Send the signal',['Transmit lever, transmitter room'],'sent'],['Keep the signal alive',['Reset any tripped signal relay'],'c2'],['Release the docking clamps',['Clamp levers along the pad railing'],'clamps'],['Board the hauler',['Ramp, east side of the pad'],'end']]}],MANI=[{nodes:[[20,110,0],[140,60,1],[140,160,1],[340,40,2],[340,110,2],[340,190,3]],pipes:[[0,1,0],[0,2,1],[1,3,-1],[1,4,2],[1,5,3],[2,4,-1],[2,5,-1]],start:[0,1,0,1],names:['North bays','South bays','Ruptured line']},{nodes:[[20,110,0],[130,60,1],[130,170,1],[240,60,1],[360,30,2],[360,120,2],[360,200,3]],pipes:[[0,1,0],[0,2,1],[1,4,2],[1,3,-1],[3,5,3],[3,6,4],[2,5,-1],[2,6,-1]],start:[0,1,0,0,1],names:['Core 1','Core 2','Leak']}];
let STORY="Nine days ago Aubade Station went dark. Its crew got out in the lifeboat. You came down alone in a one-way drop pod to bring the signal spire back. Light the spire, and the hauler Long Patience can land for you.",LOGS=[[0,'Arrival card','Ops Office','Welcome to Aubade Station, 3 km under the ice of Cerrin. Keep corridor doors shut, log your shifts, and lamps off in the ring after 22:00. Lost? Follow the amber stripes to the Mess.'],[0,'Taped inside bunk 4','J. Hale, intern',"Something keeps knocking under the floor at night, right under the round grates. Bo says it's the ice settling. The ice doesn't knock back when you knock first."],[1,'Evacuation call','Director W. Adebayo-Ross',"[alarm] This is the Director. Containment failure in the Labs. All crew to the lifeboat, now. Leave everything. Nobody is hurt and nobody is going to be. Walk, don't run. [click]"],[0,'Office whiteboard','Ops Office','EMERGENCY POWER: seat a fuse in the east corridor box, then route the relay here. Main breaker is in the Mess. Do NOT pull the breaker if you can hear ticking.'],[1,'Observation, late shift','Dr. I. Marrow',"Vael is enormous tonight. The Hum is louder too, nineteen hertz, under everything. The Borehole cultures pulse along with it. I think they're keeping time. [pause] I think they're answering."],[0,'Storage tag','T. Lindqvist, lab tech',"Shock batons are for specimen handlers ONLY. The little ones, the glassmites, curl up and go dark after one good tap. Let it recharge between shocks or it's just a stick."],[1,'Culture log 41','Dr. I. Marrow','The Borehole samples are colonial. Crawlers, spore bulbs, and something big we only see on the deep camera. Juni calls it the Lanthorn, an old word for a lantern. It carries its own light. It walks toward ours, the soft kind. Flares and the UV lamps it backs away from.'],[0,"Director's desk",'W. Adebayo-Ross',"Blue card opens Containment. The uplink key is in my wall safe in there. Whoever comes back to light the spire needs it. Containment locks down when the safe opens. I'm sorry."],[1,'Containment, last entry','Dr. I. Marrow',"[glass ticking] It's under the floor. It comes up through the service wells, the round grates with frost on them. It can't fit the crawl vents, so stay low and use them. It listens. Crouch, don't run, don't - [static] - it opens doors now. It learned the door."],[0,'Medbay chart','K. Osei, medic',"Evacuation injuries: two scrapes, one sprained ankle (Hale). Everyone walked out. If you're hurt and reading this: medkits are in the cabinets. Get out of the light first, then patch up."],[0,'Rack 7 label','P. Okonjo, life support','Sporebells are growing between the lettuce. They puff when a lamp sits on them or you stand too close. When one starts to swell, back off. Better: torch them before they swell.'],[1,'Air report','P. Okonjo','Scrubbers run on water flow. Route the manifold to both bays, pull the two bay levers, then purge from the control room. The purge is loud and takes thirty seconds. Have a plan before you start it.'],[0,"Gardener's cart",'P. Okonjo',"Weld torch is on this cart for the jammed pump-room door. It drinks fuel: chem plus a cell at the bench makes more. The pry bar works too if you have time and don't mind the noise."],[1,'Night shift','J. Hale',"[dripping] The vents are banging again. Rafe says it's the little ones, dozens of them, nesting by the warm pipes. [scratching] Okay. That's close. I'm going to the safe room. [door hiss]"],[0,'Safe room door','Ops Office','UV sterilisers on. Nothing from the Borehole will come through a UV door. If the purple lights in here ever go out, so does the safe part.'],[0,"Chief's desk",'S. Ferreira, reactor chief',"The nail driver is loaded. It won't hurt the tall one, it just tells it where you are. Use it on criers, fast, before they finish screaming."],[1,'Scram','S. Ferreira',"[klaxon] Reactor scrammed when the coolant froze. Restart: both backup generators, route coolant in control, pull the start lever, then babysit the hall valves until it's stable. The whole deck will hear it. Everything will."],[0,'Scrawled on the Gen B door','R. Ostrowski, maintenance','Boarded this from the inside and left through the vent. If you need Gen B, rip the planks. It will be loud. Go quick.'],[1,'Criers','Dr. I. Marrow',"We call them criers. They don't hunt. They call. One full scream and the Lanthorn comes straight to it. Lamp off and walk past slowly, or put them down before the throat sac fills."],[0,'Locker room board','Ops Office',"Brace doors with a bar from the scrap bin (one piece of scrap does it). It won't stop it. It buys you seconds, and seconds are a lot."],[0,'Pump room A','R. Ostrowski','Meltwater is coming up the drains from the Borehole. Three pumps, A B C, each needs a fuse and a start. The south deck stays sealed behind pressure doors until B pulls the level down.'],[1,'Wading','R. Ostrowski','[splashing] Every step in water is loud. Slower is quieter. The lures hang over the deep spots, little glowing threads. Duck under the threads. Do not walk into them.'],[0,'Flare crate','Ops Office',"Flare launcher, for surface signalling only. Added in marker, S.F.: the tall one won't step into flare light. Fourteen seconds of a corner of the world that's yours."],[1,'The deep camera','Dr. I. Marrow',"It came up the Borehole the night the seal cracked. I don't think it hates us. We sang into the deep for two years with that array, and it came up to see who was singing."],[0,'Medbay whiteboard','K. Osei',"Lifeboat docked with the hauler Long Patience. 22 crew, all safe. Pilot Varga can't land in the storms until the spire beacon is live. So someone has to come back and light it."],[0,'Spire lift','D. Kowalczyk, comms','Dish is iced over. Heaters on the west, south-west and south-east decks. Then tune the carrier in the transmitter room and send. Dress warm. The wind up here is a whole other thing.'],[1,'Comms log','D. Kowalczyk','The Hum is loudest up here. When the dish sends, the Hum answers. Last test, every light in the Labs died and something climbed toward the spire. We stopped testing.'],[0,'Observation','W. Adebayo-Ross',"If you send, it will come. Send anyway. Varga needs two minutes of clean signal to find the pad. Keep moving, keep doors between you, and don't trust the safe room tonight."],[1,'Pilot','I. Varga',"[wind] Long Patience to Aubade. If you can hear this, light the spire and I'll drop the second it's live. Two minutes of signal, no more. Hold on. I'm coming for you."],[0,'Pad procedures','Ops Office',"Three docking clamps, five seconds on each lever, don't let go early. The pulse switch dumps the pylon's charge across the whole pad: anything standing on it gets knocked flat. It takes a while to charge again."]],CHATTER=['Relay maintenance tag: replaced this fuse three times this week. Something keeps pulling it.','Sticky note: if the Sounder is quiet and the ticking is close, it is standing still. Do the same.','Lab memo: lamps off in the corridors after 22:00. Nobody remembers who made that rule.','Shift swap board: Hale owes Nakamura two dessert rations and an apology.','Hydro chalkboard: do not hum near the lettuce (Okonjo).','Reactor log: Gen A backfires if you rush the catch. Breathe, then press.','Marker on a crate: SAFE ROOMS ARE SAFE. KEEP SAYING IT.','Comms printout: carrier unstable. Something else is on our frequency.'],FAILS={open:['The Lanthorn found you.',"Lamp off when the ticking gets close: it hunts light.",'Closing a door behind you buys about four metres.',"A burning flare is a wall it won't walk through."],seen:['It saw you hide.','Break its line of sight before you hide.','Vent nooks are slow to get into. Get a head start.'],insp:['It found you behind the shutter.','Close the shutter when its light fills the slats.','Keep the shutter closed until the ticking moves away.'],spore:['The spores were too much.','Burn or shoot a sporebell before it swells.'],bite:['Something small got you.',"Wait for the baton's prongs to arc before a shock.",'Mites hate flare light. Throw one and back off.'],lure:['A lure held on too long.','Crouch to slip under glowing threads.']},BEAST=[['Lanthorn',"Tall, four-legged, stooping under our ceilings. Comes up out of the floor wells and sinks back into them. Its glass threads tick when it moves. Drawn to lamplight and noise; burned by flares, arc flash and UV. A strong shock drops it for a few seconds. Nothing we have hurts it."],['Glassmite','Hand-sized crawler with a glowing back. Packs of two to four. Brave in the dark, scared of flare light. One good shock and it goes dark.'],['Sporebell','A spore bulb. Light or closeness makes it swell, then burst into a choking cloud. Burn or shoot it first.'],['Brood sac','A warm, pulsing nest. Keeps making glassmites while you are near. Fire works best.'],['Crier',"A wall-clinger with a throat sac. It doesn't attack. It screams, and the Lanthorn comes. Kill it during the wind-up, or walk past dark and slow."],['Lure','Hangs from the ceiling with glowing threads to the floor. Step into the threads and it holds you. Duck under them.']],HINTS=[['Look around: drag the mouse, or use the Arrow keys.','Drag on the right side to look.',1],['Move with W A S D.','Use the stick on the left to move.',1],['Too dark. Press Q to switch on your lamp.','Too dark. Tap LAMP.',1],['Notes tell you what happened here. E to read.','Notes tell you what happened here. Tap USE to read.',0],['Batteries recharge your lamp. Pick it up with E. R installs one when the lamp runs low.','Batteries recharge your lamp. Tap USE to take it. RELOAD installs one when the lamp runs low.',0],['Your wrist Sounder shows things that MOVE nearby. Something just did.','Your wrist Sounder shows things that MOVE nearby. Something just did.',0],['Objectives are top left. Tab opens the station map.','Objectives are top left. MAP opens the station map.',0],['E opens and closes doors. Doors are noisy. Sprinting into them is louder.','USE opens and closes doors. Doors are noisy.',0],['E searches. Parts you find are used for crafting.','USE searches. Parts you find are used for crafting.',0],['Lockers, desks and bunks can hide you. Try one: E. E again to leave.','Lockers, desks and bunks can hide you. Try one: USE. USE again to leave.',0],["Something's coming. HIDE: get under a desk or into a locker (E).","Something's coming. HIDE: get under a desk or into a locker (USE).",1],['Stay still. It hunts by sound, and by light.','Stay still. It hunts by sound, and by light.',0],['The eye above your crosshair opens when it notices you.','The eye above your crosshair opens when it notices you.',0],["It's gone back under the floor. The frosted round grates are where it comes and goes. Lamp back on: Q.","It's gone back under the floor. The frosted round grates are where it comes and goes.",0],['Safe rooms are safe: the creatures hate the UV lamps. Progress is saved here.','Safe rooms are safe: the creatures hate the UV lamps. Progress is saved here.',0],['Craft a Battery: Cell + Wire. Space or E to craft.','Craft a Battery: Cell + Wire. Tap it to craft.',0],['Items go in pouches 5-8 on your belt. Press the number to hold one, F to use it. R puts a battery in your lamp. Keys 1-4 are for tools you will find.','Items go in the pouches on your belt. Tap one to hold it, then TOOL to use it.',0],['C crouches: slower, but almost silent.','CROUCH: slower, but almost silent.',0],['It heard that. Hide, or sneak away crouched with your lamp off.','It heard that. Hide, or sneak away crouched with your lamp off.',1],["It's gone back under the floor. The lift is east. Go.","It's gone back under the floor. The lift is east. Go.",0],['E at the console calls the lift.','USE at the console calls the lift.',0],['F swings the baton. Wait for the charge bar before shocking the big one.','TOOL swings the baton. Wait for the charge bar before shocking the big one.',0],['Get the baton from Storage before you deal with these.','Get the baton from Storage before you deal with these.',0],['Blue doors need the blue keycard.','Blue doors need the blue keycard.',0],["Vents: crouch (C) to crawl through. It can't follow.","Vents: CROUCH to crawl through. It can't follow.",0],["It heard the breaker. HIDE in the locker or vent nook. When its light fills the slats: C closes your visor.","It heard the breaker. HIDE in the locker or vent nook. When its light fills the slats: SHUTTER closes your visor.",1],['Frost on a well cover means it is about to come up there.','Frost on a well cover means it is about to come up there.',0],['Sporebells burst when you get close or shine light on them. Burn or shoot them first.','Sporebells burst when you get close or shine light on them. Burn or shoot them first.',0],['Weld torch: hold F to burn. It cuts jammed doors and welds doors shut. Up close it flashes the big one away.','Weld torch: hold TOOL to burn. It cuts jammed doors and welds doors shut.',0],['Hold E on a closed door with Scrap to brace it. It buys seconds.','Hold USE on a closed door with Scrap to brace it. It buys seconds.',0],['Criers scream for the Lanthorn. Kill them during the wind-up, or pass them dark and slow.','Criers scream for the Lanthorn. Kill them during the wind-up, or pass them dark and slow.',0],['Nail driver: F fires, R reloads. It only flinches the big one.','Nail driver: TOOL fires, RELOAD reloads. It only flinches the big one.',0],['Glowing threads: crouch (C) to slip under a lure.','Glowing threads: CROUCH to slip under a lure.',0],['Water is slow and loud. Wade carefully.','Water is slow and loud. Wade carefully.',0],["Flares: it won't walk into the light while they burn.","Flares: it won't walk into the light while they burn.",0],['Shock traps stun anything that steps on them.','Shock traps stun anything that steps on them.',0],['Hurt: H uses a Medkit.','Hurt: select a Medkit and tap TOOL.',0],['Lamp running low: R installs a Battery.','Lamp running low: RELOAD installs a Battery.',0],['Pouches full: E swaps with the selected pouch.','Pouches full: USE swaps with the selected pouch.',0],['X cycles through your item pouches.','Tap a pouch on the belt to hold it.',0],['Lights out. Lamp off. Stay still or hide.','Lights out. Lamp off. Stay still or hide.',1],['It knows where you are. A vent nook is somewhere it can\'t reach.','It knows where you are. A vent nook is somewhere it can\'t reach.',1],['Lockdown. The vent in the east wall leads to the server room (crouch: C).','Lockdown. The vent in the east wall leads to the server room (CROUCH).',1],['Wait. Let it search.','Wait. Let it search.',0],['Fight (F) or run.','Fight (TOOL) or run.',0]],H={look:0,move:1,lamp:2,read:3,bat:4,sounder:5,obj:6,door:7,search:8,hide:9,sp3:10,still:11,eye:12,gone:13,safe:14,craft:15,belt:16,crouch:17,sp4:18,gone2:19,lift:20,baton:21,nobaton:22,card:23,vent:24,shut:25,well:26,spore:27,torch:28,brace:29,crier:30,nailer:31,lure:32,water:33,flare:34,trap:35,heal:36,lowbat:37,full:38,cycle:39,dark:40,purge:41,lock:42,wait:43,fight:44},TXT={tagline:'AUBADE STATION'+DOT+'CERRIN'+DOT+'3 KM BELOW THE ICE',phones:'Headphones recommended. This game is meant to be played in the dark.',noSave:"Progress can't be saved in this browser.",empty:'Nothing in hand: 1-4 tools, 5-8 items',notFound:'Not found yet',moving:"It's moving off",shut:'SHUT VISOR',air:'AIR',credits:'Dead Signal'+DOT+'a Lowkey Arcade original',end1:'Signal received.',end2:'Long Patience lifts off from Aubade Station with one more passenger.',graceHint:'Close the shutter when its light fills the slats, and keep it closed until the ticking moves away.',seenHint:'It saw you hide. Break its line of sight first.',sp3Retry:'Hide before it arrives: desks and lockers show E.',supplies:'Supplies found near the checkpoint',lowQ:'Switched to Low quality for smoother play',lost:'Lost? Follow the cyan marker. The map outlines your objective.'},RADIO={hold:"Signal's live. I'm in the storm. Keep it up for two minutes.",trip:"Your signal's dropping! Reset it!",h60:'Halfway down. I can see the pad.',h30:'Thirty seconds. Get to the pad.',h10:'Clamps on my mark.',gate:"I'm down. Release all three clamps!",c1:'One!',c2:'Two!',c3:"That's three. Ramp's coming down.",charge:'Behind you! Hit the pulse!',board:'Got you. Hold on to something.'};
