if (Array.isArray(o.wxUntil)) for (let i = 0; i < 4; i++) S.wxUntil[i] = num(o.wxUntil[i], 0, 0, 1e7);
S.offers.length = 0; S.active.length = 0;
if (Array.isArray(o.offers)) for (let i = 0; i < o.offers.length && S.offers.length < 3; i++) { const b = readBounty(o.offers[i]); if (b) S.offers.push(b); }
if (Array.isArray(o.active)) for (let i = 0; i < o.active.length && S.active.length < 2; i++) { const b = readBounty(o.active[i]); if (b) S.active.push(b); }
S.bDay = num(o.bDay, -1, -1, 1e6) | 0;
S.caught = num(o.caught, 0, 0, 1e9) | 0;
S.earned = num(o.earned, 0, 0, 1e12);
