if (F.runT > 0) F.runT -= dt;
else if (Math.random() < dt * (0.05 + 0.22 * F.sta) * Math.min(2, F.force / cap * 2 + 0.3)) startRun(0.8 + Math.random() * 1.6 * F.sta + F.w * 0.004);
