F.lat += F.pull * (0.1 + 0.22 * F.sta) * dt * (F.runT > 0 ? 1.7 : 1);
if (F.lat > 1.2) { F.lat = 1.2; F.pull = -Math.abs(F.pull); } else if (F.lat < -1.2) { F.lat = -1.2; F.pull = Math.abs(F.pull); }
