if (sess.best < 0 || s.r > SPECIES[sess.best].r || (s.r === SPECIES[sess.best].r && F.w > sess.bestW)) { sess.best = i; sess.bestW = F.w; }
score = computeScore();
if (score > before) {
let nb = false;
try { nb = !!api.submit(score); } catch (err) { nb = false; }
if (nb) sess.newBest = true;
refreshBest();
}
landed.t = 0; landed.sp = i; landed.w = F.w; landed.l = F.l; landed.isNew = isNew; landed.rec = rec;
landed.pts = score - before; landed.price = priceOf(i, F.w, S.loc);
landed.sx = F.fx; landed.sy = waveH(F.fx, F.fz); landed.sz = F.fz;
