S.cooler.push({ sp: landed.sp, w: landed.w, l: landed.l, at: S.loc });
toast('Into the cooler (' + S.cooler.length + '/' + COOLER[S.up[3]] + ')', UI.ok);
api.tone(660, 0.08, { type: 'triangle', vol: 0.08 }); api.noise(0.1, { vol: 0.06, filter: 900, delay: 0.05 });
