let vw = 1, vh = 1, uiS = 1, LW = W, LH = H, hudDpr = 1;
const HITS = [];
for (let i = 0; i < 96; i++) HITS.push({ x: 0, y: 0, w: 0, h: 0, kind: '', arg: 0 });
