if (confirmT > 0 && confirmKey === key) { S.active.splice(i, 1); toast('Bounty abandoned.', UI.body); confirmT = 0; menuSel = 0; saveCareer(); }
else { confirmKey = key; confirmT = 2; toast('Choose it again to abandon this bounty.', UI.hi); }
