txt(ctx, fmtMoney(b.rew), cx + cw - 16, y + 20, 17, FONT_M, UI.ok, 'right', 0, 700);
txt(ctx, confirmT > 0 && confirmKey === 'ab' + i ? 'Choose again to abandon' : 'Abandon', cx + cw - 16, y + 42, 11, FONT_B, confirmT > 0 && confirmKey === 'ab' + i ? UI.bad : UI.dim, 'right', 0, 600);
