const deaf = THR_DEAF[P.thr];
txt(ctx, deaf > 0.5 ? 'DEAFENED' : deaf > 0.2 ? 'NOISY' : 'CLEAR', x + 14 + R * 2, y + 13, 10, FONT_M, deaf > 0.5 ? UI.danger : deaf > 0.2 ? UI.amber : UI.ok, 'right');
