if (P.terrWarn && P.alive && blink(now, 300)) txt(ctx, 'TERRAIN AHEAD: RISE (' + K('S', 'RISE button') + ')', gx, gy + 36, 11, FONT_M, UI.danger, 'left', 0, 700);
