const col = info.locked ? 'rgba(201,211,227,0.35)' : sel ? UI.head : UI.body;
txt(ctx, (typeof it === 'number' ? (it + 1) + '. ' : '') + info.name, lx + 20, y + rowH / 2 - 1, 13, FONT_B, col, 'left', lw - 120, 700);
