ctx.fillStyle = can ? UI.hi : 'rgba(255,255,255,0.08)'; ctx.fill();
txt(ctx, it === 'dock' ? 'OPEN DRY DOCK' : can ? 'LAUNCH' : 'LOCKED', bx + bw / 2, byy + 22, 16, FONT_D, can ? '#10151f' : UI.dim, 'center', bw - 16);
addBtn('go', bx, byy, bw, 44);
txt(ctx, touchMode ? 'Tap a mission, then LAUNCH' : 'Up/Down choose   Enter launch   D dry dock   Esc title', rx + rw / 2, VH - 16, 11, FONT_M, UI.dim, 'center', rw);
