function webglAvailable() {
try {
const c = document.createElement('canvas');
const gl = c.getContext('webgl') || c.getContext('experimental-webgl');
if (!gl) return false;
const lose = gl.getExtension('WEBGL_lose_context');
if (lose) lose.loseContext();
return true;
} catch (err) { return false; }
}

const SKY_VS = 'varying vec3 vDir;\nvoid main() {\n  vDir = position;\n  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);\n}';
const SKY_FS = [
'uniform vec3 uTop;', 'uniform vec3 uHor;', 'uniform vec3 uSun;', 'uniform vec3 uSunDir;', 'uniform float uGlow;', 'varying vec3 vDir;',
'void main() {',
'  vec3 d = normalize(vDir);',
'  float h = clamp(d.y, -1.0, 1.0);',
'  vec3 col = mix(uHor, uTop, pow(max(h, 0.0), 0.55));',
'  float s = max(dot(d, uSunDir), 0.0);',
'  col += uSun * (pow(s, 900.0) * 1.6 + pow(s, 10.0) * uGlow);',
'  if (h < 0.0) col = mix(uHor, uHor * 0.75, clamp(-h * 6.0, 0.0, 1.0));',
'  gl_FragColor = vec4(col, 1.0);',
'}'].join('\n');
const STORM_VS = 'varying vec2 vUv;\nvarying float vH;\nvoid main() {\n  vUv = uv;\n  vec4 wp = modelMatrix * vec4(position, 1.0);\n  vH = wp.y;\n  gl_Position = projectionMatrix * viewMatrix * wp;\n}';
const STORM_FS = [
'uniform float uTime;', 'uniform vec3 uCol;', 'varying vec2 vUv;', 'varying float vH;',
'void main() {',
'  float st = 0.5 + 0.5 * sin(vUv.x * 420.0 + uTime * 1.7 + sin(vUv.y * 9.0 + uTime) * 2.0);',
'  float bd = 0.5 + 0.5 * sin(vH * 0.07 - uTime * 2.3);',
'  float fade = clamp(1.0 - (vH + 20.0) / 280.0, 0.0, 1.0);',
'  float a = (0.16 + 0.3 * st * bd) * fade;',
'  gl_FragColor = vec4(uCol * (0.65 + 0.7 * st), a);',
'}'].join('\n');
const PT_VS = [
'attribute float aSize;', 'attribute vec4 aCol;', 'uniform float uScale;', 'varying vec4 vCol;',
'void main() {',
'  vCol = aCol;',
'  vec4 mv = modelViewMatrix * vec4(position, 1.0);',
'  gl_PointSize = clamp(aSize * uScale / max(-mv.z, 0.1), 1.0, 220.0);',
'  gl_Position = projectionMatrix * mv;',
'}'].join('\n');
const PT_FS = [
'uniform sampler2D uTex;', 'varying vec4 vCol;',
'void main() {',
'  vec4 t = texture2D(uTex, gl_PointCoord);',
'  float a = vCol.a * t.a;',
'  if (a < 0.01) discard;',
'  gl_FragColor = vec4(vCol.rgb * t.rgb, a);',
'}'].join('\n');

