function parseMap() {
const cell = new Uint8Array(NCELL), marks = [];
for (let z = 0; z < GH; z++) {
const row = MAP[z] || '';
for (let x = 0; x < GW; x++) {
const ch = row.charAt(x) || '#';
let t = T_FLOOR;
if (ch === '#') t = T_WALL;
else if (ch === 'w') t = T_WIN;
else if (ch === 'g') t = T_GLASS;
else if (ch === 'm') t = T_POOL;
else if (ch === '~') t = T_FLOOD;
else if ('DYRPFOM'.indexOf(ch) >= 0) t = T_DOOR;
cell[z * GW + x] = t;
if ('#.wgm~'.indexOf(ch) < 0) marks.push({ ch: ch, x: x, z: z });
}
}
return { cell: cell, marks: marks };
}

