'uniform float uTime;',
'uniform vec3 uCaus;',
'uniform vec3 uFogCol;',
'uniform float uFogNear;',
'uniform float uFogFar;',
'varying vec3 vCol;',
'varying vec3 vW;',
'void main() {',
'  float c = sin(vW.x * 1.9 + uTime * 1.2) * sin(vW.z * 1.7 - uTime) * 0.5 + 0.5;',
