ctx.beginPath(); ctx.moveTo(fx - fs * 2, fy); ctx.lineTo(fx, fy - fs * 0.8); ctx.lineTo(fx + fs * 1.4, fy);
ctx.lineTo(fx, fy + fs * 0.8); ctx.closePath(); ctx.fillStyle = 'rgba(8, 40, 52, 0.95)'; ctx.fill();
