ctx.fillStyle = cg; ctx.fillRect(0, h * 0.55, w * 0.5, h * 0.45);
const lg = ctx.createRadialGradient(w * 0.6, h * 0.12, 0, w * 0.6, h * 0.12, w * 0.24);
lg.addColorStop(0, 'rgba(255, 70, 50, 0.45)'); lg.addColorStop(1, 'rgba(255, 70, 50, 0)');
ctx.fillStyle = lg; ctx.fillRect(0, 0, w, h * 0.6);
ctx.fillStyle = '#ff6a52'; ctx.fillRect(w * 0.57, h * 0.08, w * 0.06, h * 0.018);
