const dg = ctx.createRadialGradient(mx, my - h * 0.11, 0, mx, my - h * 0.11, h * 0.2);
dg.addColorStop(0, 'rgba(180, 250, 255, 0.95)'); dg.addColorStop(0.25, 'rgba(95, 230, 255, 0.6)'); dg.addColorStop(1, 'rgba(95, 230, 255, 0)');
