ctx.fillStyle = '#d8fdff'; ctx.beginPath(); ctx.ellipse(mx, my - h * 0.1, h * 0.045, h * 0.04, 0, 0, TAU); ctx.fill();
ctx.fillStyle = '#ffb02e'; ctx.fillRect(mx - w * 0.135, my - h * 0.09, w * 0.012, h * 0.016); ctx.fillRect(mx + w * 0.123, my - h * 0.09, w * 0.012, h * 0.016);
