scene.background = new THREE.Color(BG);
scene.fog = new THREE.Fog(BG, FOG_NEAR, FOG_FAR);
const camera = new THREE.PerspectiveCamera(70, 1, 0.05, 90);
camera.rotation.order = 'YXZ';
scene.add(camera);
const tmpV = new THREE.Vector3(), tmpV2 = new THREE.Vector3(), tmpS = new THREE.Vector3(), tmpQ = new THREE.Quaternion();
const tmpM = new THREE.Matrix4(), tmpColor = new THREE.Color(), UPV = new THREE.Vector3(0, 1, 0);
const camFwd = new THREE.Vector3(0, 0, -1);
const dummy = new THREE.Object3D();
const ZERO_M = new THREE.Matrix4().makeScale(0, 0, 0);
const AMB_BASE = new THREE.Vector3(0.016, 0.02, 0.028);

const rt = keep(new THREE.WebGLRenderTarget(16, 16, {
minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, format: THREE.RGBAFormat, depthBuffer: true, stencilBuffer: false,
}));
