if (t === T_WIN || t === T_GLASS) { mctx.fillStyle = '#4fb6d6'; mctx.fillRect(px, py, MAPC, MAPC); continue; }
if (t === T_POOL) { mctx.fillStyle = '#1b7f9c'; mctx.fillRect(px, py, MAPC, MAPC); continue; }
