const DEMO_LEVEL = { idx: -1, name: 'Demo', budget: Infinity, add: [], avail: PAL.slice(), waves: parseWaves('R3S,C1S|R2E,R2W,X2N|C2N,R3S,T1W'), ch: ['none'], tip: '', treb: true, region: 0 };
let prevTool = T_WOOD;
