function pickTrebCorner() {
let best = 0, bs = 1e9;
const CX = [1, -1, 1, -1], CZ = [-1, -1, 1, 1];
for (let c = 0; c < 4; c++) {
let s = 0;
for (let w = 0; w < level.waves.length; w++) for (let g = 0; g < level.waves[w].length; g++) {
const d = level.waves[w][g].d;
if ((d === 1 && CX[c] > 0) || (d === 3 && CX[c] < 0) || (d === 0 && CZ[c] > 0) || (d === 2 && CZ[c] < 0)) s += level.waves[w][g].n;
}
if (s < bs) { bs = s; best = c; }
}
trebX = CX[best] * 11.2; trebZ = CZ[best] * 11.2; trebYaw = Math.atan2(-trebX, -trebZ);
}
