g.drawImage(crowd, LW - 24, off - 200); g.drawImage(crowd, LW - 24, off);
const top = camR + 24.5, bot = camR - 16.5;
for (let y = Math.floor(bot / 5) * 5; y < top; y += 5) { // grass bands and end zones
if (y < -10 || y >= 110) continue;
const s0 = wy(y + 5), s1 = wy(y);
g.fillStyle = y < 0 ? offT.dk : y >= 100 ? defT.dk : ((y / 5) & 1) ? PAL.grass1 : PAL.grass2;
g.fillRect(FX0, s0, FWPX, s1 - s0);
}
