for (let y = y0; y <= y1; y++) { // yard lines and hash marks
const sy = wy(y);
if (y % 5 === 0) g.fillRect(FX0, sy, FWPX, y === 0 || y === 100 ? 2 : 1);
else { g.fillRect(FX0 + 1, sy, 3, 1); g.fillRect(FX0 + FWPX - 4, sy, 3, 1); g.fillRect(wx(23.6), sy, 3, 1); g.fillRect(wx(29.7) - 3, sy, 3, 1); }
}
