const len = aimTarget(), q = R.qb, lob = len > 34;
const qx = wx(q.x), qy = wy(q.y);
pline(qx, qy - 6, qx + (aim.px - aim.ax), qy - 6 + (aim.py - aim.ay), 'rgba(255, 255, 255, 0.45)', 2);
