hr(x, y, s, 4, 0, 5, 1); hr(x, y, s, 2, 1, 8, 1); hr(x, y, s, 1, 2, 10, 1); hr(x, y, s, 0, 3, 11, 2);
hr(x, y, s, 0, 5, 8, 1); hr(x, y, s, 1, 6, 6, 1); hr(x, y, s, 2, 7, 4, 1);
