let SIN=new Int32Array(1280);(function(){let a=0,b=0.0061358846491544753;let C2=2*0.99998117528260111;SIN[0]=0;SIN[1]=Math.round(b*1024);for(let k=1;k<1279;k++){let c=C2*b-a;a=b;b=c;SIN[k+1]=Math.round(c*1024);}})();function isin(a){return SIN[a&1023];}
function icos(a){return SIN[(a+256)&1023];}
