if (isSel) { sc *= 1.08 + 0.03 * Math.sin(clock * 6); y -= 2; }
if (sc <= 0.02) return;
ctx.save();
ctx.translate(x, y);
if (rot) ctx.rotate(rot);
ctx.scale(sc * sx, sc * sy);
drawCrystal(g.type, g.sp);
if (g.lk) drawLock();
if (white > 0) {                               // flash white as it shatters
ctx.globalCompositeOperation = 'lighter';
ctx.globalAlpha = 0.6 * white;
if (g.sp === SP_PRISM) { ctx.fillStyle = '#FFFFFF'; ctx.beginPath(); ctx.arc(0, 0, CELL * 0.4, 0, TAU); ctx.fill(); }
else drawSprite(g.type);
}
