ctx.beginPath(); ctx.arc(PAUSE_X, PAUSE_Y, 17, 0, TAU);
ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.fill();
ctx.strokeStyle = 'rgba(255,255,255,0.22)'; ctx.lineWidth = 1.5; ctx.stroke();
ctx.fillStyle = C_BODY; ctx.fillRect(PAUSE_X - 6, PAUSE_Y - 7, 4, 14); ctx.fillRect(PAUSE_X + 2, PAUSE_Y - 7, 4, 14);
